package io.github.jesterportfolio.hearth.quest;

import io.github.jesterportfolio.hearth.exploration.*;
import io.github.jesterportfolio.hearth.persistence.*;
import io.github.jesterportfolio.hearth.story.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

final class CourseResumeTest {
    static QuestCatalog catalog(){var rows=new ArrayList<Map<String,Object>>();for(String id:List.of("main","report","failed","paid","waiting","skipped","done","future")){var q=QuestCatalogTest.quest(id,"guide");if(id.equals("future"))q.put("title","미수락 미래 비공개 정의");if(id.equals("main")){q.remove("objective");q.put("objectives",List.of(Map.of("description","현재 저장 목표","min-x",12,"max-x",14,"min-y",64,"max-y",67,"min-z",12,"max-z",14),Map.of("description","현재 저장 목표","min-x",15,"max-x",16,"min-y",64,"max-y",67,"min-z",12,"max-z",14)));}rows.add(q);}return QuestCatalog.parse(List.of(QuestCatalogTest.npc("guide",3)),rows);}
    static Playthrough plan(){return new Playthrough(List.of(new Playthrough.Step("first",Playthrough.Kind.QUEST,"main","현재 개인 조사","기존 현장에서 계속하세요."),new Playthrough.Step("future",Playthrough.Kind.QUEST,"future","미수락 미래 비공개 정의","숨긴 미래 설명")));}
    static QuestJournal.View view(){var states=new HashMap<String,QuestStore.Saved>();for(String id:catalog().questIds())states.put(id,new QuestStore.Saved(QuestStore.Phase.NOT_ACCEPTED,-1));states.put("main",new QuestStore.Saved(QuestStore.Phase.ACTIVE,0,0));states.put("report",new QuestStore.Saved(QuestStore.Phase.REPORT_READY,1));states.put("failed",new QuestStore.Saved(QuestStore.Phase.FAILED,2));states.put("paid",new QuestStore.Saved(QuestStore.Phase.COMPLETED,3));states.put("skipped",new QuestStore.Saved(QuestStore.Phase.SKIPPED,0));states.put("done",new QuestStore.Saved(QuestStore.Phase.COMPLETED,2));return new QuestJournal.View(states,new QuestJournalStore.Journal(Set.of("main","failed"),new QuestJournalStore.Preferences(true,0),List.of()),ExplorationView.empty(),new QuestCompletionView(true,4,Map.of("paid",new QuestCompletionView.Reward("PENDING","개인 지급 대기",true),"skipped",new QuestCompletionView.Reward("POLICY_PENDING","미정",false)),List.of()));}
    static CourseResume.Board board(QuestJournal.View view){return CourseResume.build(plan(),catalog(),view,SharedStoryTest.empty(),SharedStory.Phase.READY);}
    @Test void combinesCurrentSavedGoalReportingRetryAndClaimableRewardWithoutFutureOrSkippedRows(){var b=board(view());assertEquals(List.of("main","report","failed","paid"),b.rows().stream().map(CourseResume.Row::quest).toList());assertEquals(List.of(CourseResume.Kind.ACTIVE,CourseResume.Kind.REPORT,CourseResume.Kind.FAILED,CourseResume.Kind.REWARD),b.rows().stream().map(CourseResume.Row::kind).toList());assertTrue(b.rows().getFirst().current());assertTrue(b.rows().getFirst().tracked());assertFalse(String.join(" ",b.book(1).pages()).contains("미수락 미래"));assertTrue(b.book(1).pages().stream().anyMatch(p->p.contains("개인 지급 대기")));}
    @Test void initialUnacceptedCourseUsesPublicNextActionWithoutInventingResumeRows(){var v=view();var rows=new HashMap<String,QuestStore.Saved>();for(String id:catalog().questIds())rows.put(id,new QuestStore.Saved(QuestStore.Phase.NOT_ACCEPTED,-1));var b=board(new QuestJournal.View(rows,v.journal(),v.exploration()));assertTrue(b.available());assertTrue(b.rows().isEmpty());assertEquals("main",b.course().guide().talkQuest());assertFalse(b.course().guide().complete());assertEquals(1,b.coursePage());}
    @Test void holdBusyAndUnconfirmedSharedRevisionCannotLookLikeSuccessfulResume(){for(var phase:SharedStory.Phase.values())if(phase!=SharedStory.Phase.READY&&phase!=SharedStory.Phase.OPEN){var b=CourseResume.build(plan(),catalog(),view(),SharedStoryTest.empty(),phase);assertFalse(b.available());assertTrue(b.rows().isEmpty());assertFalse(b.course().guide().complete());assertThrows(IllegalStateException.class,()->CourseResume.require(b,b,1,null));}var v=view();var x=v.exploration();var story=new ExplorationStore.Story(null,null,null,3);var altered=new QuestJournal.View(v.states(),v.journal(),new ExplorationView(x.registered(),x.regions(),x.places(),x.facts(),x.events(),x.members(),story,x.conditions(),x.nextGoal(),x.blockedQuests(),x.branches()),v.completion());assertFalse(board(altered).available());}
    @Test void blockedQuestAndNpcLocationRemoveActionablePersonalRows(){var v=view();var x=v.exploration();var blocked=new ExplorationView(x.registered(),x.regions(),x.places(),x.facts(),x.events(),x.members(),x.story(),x.conditions(),x.nextGoal(),Set.of("failed","paid"),x.branches());var b=board(new QuestJournal.View(v.states(),v.journal(),blocked,v.completion()));assertEquals(Set.of("main","report"),b.rows().stream().map(CourseResume.Row::quest).collect(java.util.stream.Collectors.toSet()));assertTrue(board(new QuestJournal.View(v.states(),v.journal(),v.exploration(),v.completion(),Set.of("guide"))).rows().isEmpty());}
    @Test void grantedUnregisteredAndPolicyPendingRewardsAreNotClaimableResumeTasks(){var v=view();for(String status:List.of("GRANTED","NONE","UNREGISTERED","POLICY_PENDING","CONFIG_MISMATCH")){var c=new QuestCompletionView(true,5,Map.of("paid",new QuestCompletionView.Reward(status,"보상 상태",false)),List.of());assertFalse(board(new QuestJournal.View(v.states(),v.journal(),v.exploration(),c)).rows().stream().anyMatch(r->r.quest().equals("paid")));}assertFalse(board(new QuestJournal.View(v.states(),v.journal(),v.exploration())).rows().stream().anyMatch(r->r.quest().equals("paid")));}
    @Test void sameTextGoalRevisionTrackingAndRewardEpochChangesRejectPreviousChoice(){var v=view();var shown=board(v);for(var saved:List.of(new QuestStore.Saved(QuestStore.Phase.ACTIVE,1,0),new QuestStore.Saved(QuestStore.Phase.ACTIVE,1,1))){var rows=new HashMap<>(v.states());rows.put("main",saved);assertThrows(IllegalStateException.class,()->CourseResume.require(board(new QuestJournal.View(rows,v.journal(),v.exploration(),v.completion())),shown,1,shown.rows().getFirst()));}var tracked=new QuestJournalStore.Journal(Set.of(),v.journal().preferences(),v.journal().notices());assertThrows(IllegalStateException.class,()->CourseResume.require(board(new QuestJournal.View(v.states(),tracked,v.exploration(),v.completion())),shown,1,null));var epoch=new QuestCompletionView(true,5,v.completion().rewards(),List.of());assertThrows(IllegalStateException.class,()->CourseResume.require(board(new QuestJournal.View(v.states(),v.journal(),v.exploration(),epoch)),shown,1,null));}
    @Test void sharedConditionsAppearOnlyForCurrentSharedStepAndOldConditionSnapshotIsRejected(){var v=view();var p=new Playthrough(List.of(new Playthrough.Step("shared",Playthrough.Kind.STAGE,"public_stage","공동 조사 준비","현재 공개 조건을 확인하세요.")));var b=CourseResume.build(p,catalog(),v,SharedStoryTest.empty(),SharedStory.Phase.READY);assertEquals(v.exploration().conditions().lines(),b.sharedConditions());var x=v.exploration();var changed=new QuestJournal.View(v.states(),v.journal(),new ExplorationView(x.registered(),x.regions(),x.places(),x.facts(),x.events(),x.members(),x.story(),new CommunityBoundary.Status(true,List.of("현재 접속자 조건 확인 필요")),x.nextGoal(),x.blockedQuests(),x.branches()),v.completion());var fresh=CourseResume.build(p,catalog(),changed,SharedStoryTest.empty(),SharedStory.Phase.READY);assertThrows(IllegalStateException.class,()->CourseResume.require(fresh,b,1,null));assertTrue(board(v).sharedConditions().isEmpty());}
    @Test void courseGuidanceCompletionDoesNotErasePersonalRewardAndHasSafeCoursePage(){var v=view();var p=new Playthrough(List.of(new Playthrough.Step("done",Playthrough.Kind.QUEST,"paid","개인 완료 기록","기록 확인")));var b=CourseResume.build(p,catalog(),v,SharedStoryTest.empty(),SharedStory.Phase.READY);assertTrue(b.course().guide().complete());assertTrue(b.rows().stream().anyMatch(r->r.kind()==CourseResume.Kind.REWARD));assertEquals(1,b.coursePage());}
    @Test void pageSelectionIsBoundToDisplayedRowsAndReadOnlyListsAreImmutable(){var npcs=List.of(QuestCatalogTest.npc("guide",3));var definitions=new ArrayList<Map<String,Object>>();var states=new HashMap<String,QuestStore.Saved>();for(int i=0;i<15;i++){String id="quest_"+i;definitions.add(QuestCatalogTest.quest(id,"guide"));states.put(id,new QuestStore.Saved(QuestStore.Phase.ACTIVE,0));}var c=QuestCatalog.parse(npcs,definitions);var v=new QuestJournal.View(states,view().journal());var p=new Playthrough(List.of(new Playthrough.Step("first",Playthrough.Kind.QUEST,"quest_0","현재 의뢰","진행 안내")));var b=CourseResume.build(p,c,v,SharedStoryTest.empty(),SharedStory.Phase.READY);assertEquals(3,b.pages());assertEquals(3,b.page(3).size());assertThrows(IllegalStateException.class,()->CourseResume.require(b,b,1,b.page(2).getFirst()));assertThrows(IllegalArgumentException.class,()->CourseResume.require(b,b,0,null));assertThrows(UnsupportedOperationException.class,()->b.rows().clear());assertThrows(UnsupportedOperationException.class,()->b.rows().getFirst().lines().clear());}
    @Test void repeatedResumeReadsDoNotChangeStoredStateOrAutomaticallyTrackRetryOrPay(){var v=view();String before=v.toString();var b=board(v);assertEquals(b,board(v));b.book(1);CourseResume.require(b,b,1,b.rows().getFirst());assertEquals(before,v.toString());assertEquals(QuestStore.Phase.FAILED,v.states().get("failed").phase());assertTrue(v.completion().rewards().get("paid").claimable());}
}
